{
  "schema_version": "0.1",
  "report_id": "R_b9d5c02eae1e5eca89d050023052b085",
  "recommendation": "HOLD",
  "claims": [
    {
      "claim_id": "C1",
      "text": "Total revenue, net of interest expense, increased by 6.84% from $105,856 million in 2024 to $113,097 million in 2025.",
      "evidence_ids": [
        "EP_0004_E01"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0004_F02",
        "to_fact_id": "EP_0004_F01",
